pub static STRIPE: Icon = Icon { name: "channel-stripe", view: 512.0, body: r##"<rect width="512" height="512" rx="64" fill="#533AFD"/><path d="M120 392 392 334.317V120L120 178.357z" fill="#fff"/>"## };

/// The mark for a channel key, as the web's `ChannelMark` picks it; `None` draws the globe.
pub fn for_channel(key: &str) -> Option<&'static Icon> {
    Some(match key {
        "ga4" => &GA4,
        "github" | "profile:GITHUB" => &GITHUB,
        "search-console" => &SEARCH_CONSOLE,
        "meta" => &META,
        "google_ads" => &GOOGLE_ADS,
        "google_business" | "profile:GOOGLE_BUSINESS" => &GOOGLE,
        "wordpress" => &WORDPRESS,
        "stripe" => &STRIPE,
        "profile:FACEBOOK" => &FACEBOOK,
        "profile:INSTAGRAM" => &INSTAGRAM,
        "profile:YOUTUBE" => &YOUTUBE,
        "profile:X" => &X,
        "profile:TIKTOK" => &TIKTOK,
        "profile:PINTEREST" => &PINTEREST,
        "profile:YELP" => &YELP,
        "profile:G2" => &G2,
        "profile:PRODUCT_HUNT" => &PRODUCT_HUNT,
        "profile:LINKEDIN" => &LINKEDIN,
        _ => return None,
    })
}
